      [("Éthanol + permanganate", ["Multiplier l'oxydant par 2 et l'alcool par 5 (10 e⁻).", "2MnO₄⁻ + 6H⁺ + 5CH₃CH₂OH → 2Mn²⁺ + 8H₂O + 5CH₃CHO."])],
